detail_find_rule:
js:
var d = [];
var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');
var host = 'https://' + 'api.example.com';

// 1. 获取主剧元数据
var mediaId = currentUrl.match(/\/detail\/([a-zA-Z0-9_-]+)/) ? currentUrl.match(/\/detail\/([a-zA-Z0-9_-]+)/)[1] : '';
var metaApi = host + '/api/v1/media/detail?id=' + mediaId;
var seriesTitle = '影视详情';
var intro = '';
var cover = '';
var routes = [];

try {
  var json = JSON.parse(request(metaApi, { headers: { 'User-Agent': 'PC' } }));
  var detail = json.data || {};
  seriesTitle = detail.title || seriesTitle;
  intro = detail.intro || detail.summary || '';
  cover = detail.cover || '';
  routes = detail.routes || detail.sources || [];
} catch (e) {}

// 详情页首项：必须显式注入父剧名契约（铁律 5）
d.push({
  title: '剧名：' + seriesTitle,
  desc: intro,
  pic_url: cover ? cover + '@Referer=' + host : '',
  url: currentUrl,
  col_type: 'pic_1_card'
});

// 2. 多层级分支判断：
// 若有多个线路/分季，通过 @rule= 输出二级下潜卡片（模式 A）
if (routes && routes.length > 1) {
  d.push({
    title: '请选择播放线路 / 分季：',
    col_type: 'text_1'
  });

  routes.forEach(function(route) {
    var routeId = route.id;
    var routeName = route.name || '播放专线';
    var routeUrl = host + '/api/v1/media/episodes?id=' + mediaId + '&source=' + routeId;

    // 动态生成三级选集页的规则（通过闭包注入 parentTitle 和 routeName）
    var nextTierRule = '.js:(' + function(pTitle, rName, h) {
      var d = [];
      var currentUrl = (typeof MY_URL !== 'undefined' && MY_URL) ? MY_URL : (typeof input !== 'undefined' ? input : '');

      // 三级页面首项：必须保持父剧名（防止历史记录变纯分集名）
      d.push({
        title: '剧名：' + pTitle,
        desc: '当前线路：' + rName,
        url: currentUrl,
        col_type: 'text_1'
      });

      try {
        var resp = JSON.parse(request(currentUrl, { headers: { 'User-Agent': 'PC' } }));
        var eps = resp.data && resp.data.episodes ? resp.data.episodes : [];
        eps.forEach(function(ep, idx) {
          var epTitle = ep.title || ('第' + (idx + 1) + '集');
          var epPlayUrl = ep.play_url || ep.url;

          d.push({
            title: epTitle,
            url: epPlayUrl + '@lazyRule=.js:(() => { return input + ";{Referer@' + h + '&&User-Agent@PC}"; })()',
            col_type: 'text_3'
          });
        });
      } catch (err) {}
      setResult(d);
    }.toString() + ')(' + JSON.stringify(seriesTitle) + ', ' + JSON.stringify(routeName) + ', ' + JSON.stringify(host) + ')';

    d.push({
      title: '【' + routeName + '】',
      desc: route.tip || '包含超清画质，点击进入选集',
      pic_url: '',
      url: routeUrl + '@rule=' + nextTierRule,
      col_type: 'text_2'
    });
  });
} else {
  // 仅单线路或直接穿透获取剧集（模式 B：深度异步穿透）
  d.push({
    title: '播放列表：',
    col_type: 'text_1'
  });

  var epApi = host + '/api/v1/media/episodes?id=' + mediaId;
  try {
    var epJson = JSON.parse(request(epApi, { headers: { 'User-Agent': 'PC' } }));
    var eps = epJson.data && epJson.data.episodes ? epJson.data.episodes : [];
    eps.forEach(function(ep, idx) {
      var epTitle = ep.title || ('第' + (idx + 1) + '集');
      var epPlayUrl = ep.play_url || ep.url;
      d.push({
        title: epTitle,
        url: epPlayUrl + '@lazyRule=.js:(() => { return input + ";{Referer@' + host + '&&User-Agent@PC}"; })()',
        col_type: 'text_3'
      });
    });
  } catch (e) {}
}

setResult(d);

